import pandas as pd

def get_district(client_df, loan_df):
    female_client = client_df[(client_df['gender'] == 'F') & (client_df['birth_date'] == '1976-01-29')]
    if not female_client.empty:
        district_id = female_client['district_id'].iloc[0]
        district = loan_df.loc[loan_df['district_id'] == district_id, 'district_id'].head(1)
        return district.iloc[0]
    else:
        return None

# Example usage:
client_df = pd.DataFrame({
    'client_id': [1, 2, 3],
    'gender': ['F', 'M', 'F'],
    'birth_date': ['1976-01-29', '1975-01-29', '1977-01-29'],
    'district_id': [1, 2, 3]
})

loan_df = pd.DataFrame({
    'district_id': [1, 2, 3, 4, 5],
    'district': ['District A', 'District B', 'District C', 'District D', 'District E']
})

print(get_district(client_df, loan_df))
```

