import pandas as pd

def count_accounts_from_jesenik(df_account, df_district):
    jesenik_id = df_district.loc[df_district['A2'] == 'Jesenik', 'district_id'].iloc[0]
    return (df_account['district_id'] == jesenik_id).sum()
